import pytest

from upadup.dep_parser import (
    SpecifierParseError,
    UnsupportedSpecifierError,
    parse_specifier,
)


@pytest.mark.parametrize(
    "specifier",
    (
        "xyz===1.0",
        "xyz===   1.0",
        "xyz ~= 2.1-dev0",
        "foo==1",
        "foo == 1.0",
        "foo==2.2 ",
        "  foo==1.1b0",
    ),
)
def test_parse_and_format_roundtrips(specifier):
    parsed = parse_specifier(specifier)
    assert specifier == parsed.format()


@pytest.mark.parametrize(
    "specifier",
    (
        "xyz=1.0",
        "xyz>=1.0",
        "xyz<=1.0",
        "xyz>=1.0,<=1.0",
        "xyz!=1.0",
    ),
)
def test_parse_requires_double_equal(specifier):
    with pytest.raises(UnsupportedSpecifierError):
        parse_specifier(specifier)


@pytest.mark.parametrize(
    "specifier",
    (
        "xyz abc == 1.0",
        "xyz==1.0 2.1",
    ),
)
def test_parse_rejects_specifier_with_invalid_whitespace(specifier):
    with pytest.raises(SpecifierParseError):
        parse_specifier(specifier)


@pytest.mark.parametrize("comparator", ("===", "==", "~="))
def test_parse_and_update_version(comparator):
    spec = parse_specifier(f"foo{comparator}1.0.0")
    spec2 = spec.update_version("1.1.1")
    # unchanged
    assert spec.format() == f"foo{comparator}1.0.0"
    # changed!
    assert spec2.format() == f"foo{comparator}1.1.1"

import os
import pathlib
import re
from textwrap import dedent as d

import pytest

from upadup.config import BadConfigError, Config


@pytest.fixture
def in_tmp_dir(tmp_path):
    cwd = pathlib.Path.cwd()
    try:
        os.chdir(tmp_path)
        yield tmp_path
    finally:
        os.chdir(cwd)


def test_no_config_is_valid_and_defines_no_skip_repos(in_tmp_dir):
    c = Config.load()
    assert isinstance(c, Config)
    assert c.skip_repos == ()


@pytest.mark.parametrize("config_file_name", [".upadup.toml", "pyproject.toml"])
@pytest.mark.parametrize("file_contents", ["\n", "[tool]\n", "[tool.upadup]\n"])
def test_empty_config_is_valid_and_defines_no_skip_repos(
    in_tmp_dir, config_file_name, file_contents
):
    config_file = in_tmp_dir / config_file_name
    config_file.write_text(file_contents)

    c = Config.load()
    assert isinstance(c, Config)
    assert c.skip_repos == ()


@pytest.mark.parametrize("config_file_name", [".upadup.toml", "pyproject.toml"])
@pytest.mark.parametrize(
    "file_contents, expect_message",
    [
        ("tool = []\n", "'tool' was not a table"),
        ("tool.upadup = []\n", "'tool.upadup' was not a table"),
        ("tool.upadup.skip_repos = 1\n", "'tool.upadup.skip_repos' should be a list"),
        (
            "tool.upadup.skip_repos = ['a', 1]\n",
            "'tool.upadup.skip_repos[1]' was not a string",
        ),
    ],
)
def test_malformed_config_is_rejected(
    in_tmp_dir, config_file_name, file_contents, expect_message
):
    config_file = in_tmp_dir / config_file_name
    config_file.write_text(file_contents)

    with pytest.raises(BadConfigError, match=re.escape(expect_message)):
        Config.load()


@pytest.mark.parametrize("config_file_name", [".upadup.toml", "pyproject.toml"])
@pytest.mark.parametrize(
    "file_contents, expect_skip_repos",
    [
        ("tool.upadup = {skip_repos = ['foo']}\n", ("foo",)),
        (
            d(
                """\
            [tool.upadup]
            skip_repos = []
            """
            ),
            (),
        ),
        (
            d(
                """\
            [tool.upadup]
            skip_repos = ['a', 'b', 'c']
            """
            ),
            ("a", "b", "c"),
        ),
    ],
)
def test_config_with_skip_repos_config(
    in_tmp_dir, config_file_name, file_contents, expect_skip_repos
):
    config_file = in_tmp_dir / config_file_name
    config_file.write_text(file_contents)

    c = Config.load()
    assert c.skip_repos == expect_skip_repos

import re
import typing as t
from collections.abc import Mapping

import requests

# this normalization pattern follows the rules declared for package normalization
# on pypi itself
# newer build backends are guaranteed to canonicalize the name portion of dist files
# to this form, and other ecosystem components may also rely on this canonical form
_NORMALIZATION_PATTERN = re.compile(r"[-_.]+")


def _normalize_package_name(name: str) -> str:
    return _NORMALIZATION_PATTERN.sub("-", name).lower()


def get_pkg_latest(name: str) -> str:
    version_data = requests.get(f"https://pypi.python.org/pypi/{name}/json", timeout=30)
    return str(version_data.json()["info"]["version"])


class VersionMap(Mapping[str, str]):
    def __init__(self) -> None:
        self._cache: dict[str, str] = {}

    def __getitem__(self, key: str) -> str:
        normed = _normalize_package_name(key)
        self._populate(normed)
        return self._cache[normed]

    def __contains__(self, key: object) -> bool:
        if not isinstance(key, str):
            return False
        normed = _normalize_package_name(key)
        return normed in self._cache

    def __iter__(self) -> t.Iterator[str]:
        yield from self._cache

    def __len__(self) -> int:
        return len(self._cache)

    def _populate(self, package_name: str) -> None:
        if package_name not in self._cache:
            self._cache[package_name] = get_pkg_latest(package_name)
